source.paragraph:
\begin{definition}
\label{definition-skew-field}
A {\it skew field} is a possibly noncommutative ring with an identity
element $1$, with $1 \not = 0$, in which every nonzero element
has a multiplicative inverse.
\end{definition}

target.paragraph:
\begin{definition}
\label{brauer-definition-skew-field}
{\it 나눗셈환}이란 항등원 $1$을 가지고 $1 \not = 0$이며, 모든 영이 아닌
원이 곱셈 역원을 갖는, 비가환일 수도 있는 환을 말한다.
\end{definition}

source.paragraph:
\begin{lemma}
\label{lemma-simple-module}
Let $A$ be a $k$-algebra. If $A$ is finite, then
\begin{enumerate}
\item $A$ has a simple module,
\item any nonzero module contains a simple submodule,
\item a simple module over $A$ has finite dimension over $k$, and
\item if $M$ is a simple $A$-module, then $\text{End}_A(M)$ is a
skew field.
\end{enumerate}
\end{lemma}

target.paragraph:
\begin{lemma}
\label{brauer-lemma-simple-module}
$A$를 $k$-대수라 하자. $A$가 유한이면 다음이 성립한다.
\begin{enumerate}
\item $A$는 단순 가군을 갖는다.
\item 영이 아닌 모든 가군은 단순 부분가군을 포함한다.
\item $A$ 위의 단순 가군은 $k$ 위에서 유한 차원이다.
\item $M$이 단순 $A$-가군이면 $\text{End}_A(M)$은 나눗셈환이다.
\end{enumerate}
\end{lemma}

